import { DashboardSidebar } from "@/components/layout/dashboard-sidebar";
import { DashboardHeader } from "@/components/layout/dashboard-header";
import { DashboardShellProvider } from "@/components/layout/dashboard-shell-provider";
import { ThemeProvider } from "@/components/theme/theme-provider";

export default function DashboardLayout({
  children,
}: Readonly<{ children: React.ReactNode }>) {
  return (
    <ThemeProvider>
      <DashboardShellProvider>
        <div
          data-theme-scope="authenticated"
          className="flex min-h-screen overflow-x-hidden bg-background text-foreground"
        >
          <DashboardSidebar />
          <div className="flex min-w-0 flex-1 flex-col">
            <DashboardHeader />
            <main className="flex-1 px-4 py-6 sm:px-6 lg:ml-64 lg:px-8 lg:py-8">
              {children}
            </main>
          </div>
        </div>
      </DashboardShellProvider>
    </ThemeProvider>
  );
}
